import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintStream out = System.out;

        int t = 1;
        List<int[]> permutationsList = generatePermutations(new int[]{1, 2, 3, 4, 5, 6});
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = parseLineToIntArray(br.readLine());
        int[] b = parseLineToIntArray(br.readLine());

        int maxMatch = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        int maxResult = 0;

        for (int[] perm : permutationsList) {
            int[] ta = a.clone();
            int[] tb = b.clone();
            int total = 0;
            for (int el : perm) {
                int t = 0;
                switch (el) {
                    case 1:
                        t = Math.min(ta[0], tb[0]);
                        ta[0] -= t;
                        tb[0] -= t;
                        total += t;
                        break;
                    case 2:
                        t = Math.min(ta[0], tb[2]);
                        ta[0] -= t;
                        tb[2] -= t;
                        total += t;
                        break;
                    case 3:
                        t = Math.min(ta[1], tb[1]);
                        ta[1] -= t;
                        tb[1] -= t;
                        total += t;
                        break;
                    case 4:
                        t = Math.min(ta[1], tb[0]);
                        ta[1] -= t;
                        tb[0] -= t;
                        total += t;
                        break;
                    case 5:
                        t = Math.min(ta[2], tb[2]);
                        ta[2] -= t;
                        tb[2] -= t;
                        total += t;
                        break;
                    case 6:
                        t = Math.min(ta[2], tb[1]);
                        ta[2] -= t;
                        tb[1] -= t;
                        total += t;
                        break;
                }
            }
            maxResult = Math.max(maxResult, total);
        }

        out.print((n - maxResult) + " " + maxMatch);
    }

    static List<int[]> generatePermutations(int[] arr) {
        List<int[]> permutations = new ArrayList<>();
        permute(arr, 0, permutations);
        return permutations;
    }

    static void permute(int[] arr, int l, List<int[]> permutations) {
        if (l == arr.length - 1) {
            permutations.add(arr.clone());
        } else {
            for (int i = l; i < arr.length; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, permutations);
                swap(arr, l, i);
            }
        }
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    static int[] parseLineToIntArray(String line) {
        String[] parts = line.trim().split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}
